  <view class="product-grid"><view v-for="p in products" :key="p.id" class="product-tile" @tap="go('product',{id:p.id})"><FoodPhoto :image="p.image"/><view class="product-tile-info"><text class="strong">{{p.name}}</text><text class="small muted block mt4">{{p.spec}} · {{p.unit}}</text><view class="row between mt8"><text class="price strong">¥{{money(p.price)}}<text class="unit"> / {{p.unit}}</text></text><button class="add-button" :disabled="busy" :aria-label="'添加'+p.name" @tap.stop="add(p)">+</button></view></view></view></view><view v-if="!products.length" class="empty"><FIcon name="search" :size="40"/><text>没有找到相关食材</text><text class="muted small">换个关键词，或选择其他分类</text></view>
 </template>
 <template v-else-if="screen==='product'">
  <template v-if="product"><FoodPhoto :image="product.image" class="product-hero" variant="product-hero"/><view class="card"><text class="large-title">{{product.name}}</text><view class="price price-big mt8">¥{{money(product.price)}}<text class="unit"> / {{product.unit}}</text></view><view class="row mt16"><text class="badge completed">✓ 当日鲜采</text><text class="badge completed">散装称重</text></view><text class="muted small block mt16">{{product.description}}</text><view class="spec-list mt16"><view><text>计价单位</text><text>{{product.unit}}</text></view><view><text>起订数量</text><text>{{product.minimum}}{{product.unit}}</text></view><view><text>配送供应商</text><text>{{store?.supplierName||'待平台绑定'}}</text></view><view><text>配送说明</text><text>每日鲜采，准时送达</text></view></view></view><view class="card"><text class="strong">适用场景</text><text class="muted block mt12">适合食堂日常备餐，按需采购。订单提交后由负责门店的供应商配送。</text></view><view class="action-bar"><Stepper :model-value="productQuantity" :minimum="Number(product.minimum)" :label="product.name" @change="productQuantity=Math.max(Number(product.minimum),$event)"/><button class="btn grow" :disabled="busy" @tap="addProduct">加入购物车</button><button class="icon-button" aria-label="查看购物车" @tap="go('cart')"><FIcon name="cart"/></button></view></template><view v-else class="empty">该食材已下架或不存在</view>
 </template>
 <template v-else-if="screen==='cart'">
  <view class="card"><view class="row"><FIcon name="store"/><view><text class="strong">{{store?.name}}</text><text class="block small muted mt4">{{store?.supplierName||'待绑定供应商'}}（定向配送）</text></view></view><view v-for="item in cart" :key="item.id" class="cart-row"><button class="check-circle" :class="{checked:!excluded.includes(item.id)}" :aria-label="'选择'+item.name" @tap="toggleItem(item.id)"><text v-if="!excluded.includes(item.id)">✓</text></button><FoodPhoto :image="item.image"/><view class="grow"><text class="strong">{{item.name}}</text><text class="price small block mt8">¥{{money(item.price)}} / {{item.unit}}</text><view class="row between mt8"><Stepper :model-value="Number(item.quantity)" :minimum="Number(item.minimum)" :disabled="busy" :label="item.name" @change="setCart(item.id,$event)"/><text class="price strong small">¥{{money(lineAmount(item.price,item.quantity))}}</text></view></view></view><view v-if="!cart.length" class="empty"><FIcon name="cart" :size="42"/><text>购物车还是空的</text><button class="btn small-btn mt16" @tap="go('home',{},true)">去选购食材</button></view></view>
  <view v-if="cart.length" class="card"><view class="row between"><text class="strong">商品金额</text><text class="price price-big">¥{{money(cartTotal)}}</text></view><text class="small muted block mt8">共{{selectedCart.length}}种食材，{{cartQuantity}}</text></view><view class="notice"><view class="row strong"><FIcon name="help" :size="18"/>提交后自动分配给负责供应商</view><text class="block small muted mt8">根据门店绑定关系自动分单，由平台与门店统一线下结算。</text></view><view class="action-bar above-nav"><button class="text-button row" @tap="excluded=excluded.length?[]:cart.map(i=>i.id)"><text class="check-circle" :class="{checked:!excluded.length}">✓</text>全选</button><view class="grow align-right small">合计 <text class="price strong">¥{{money(cartTotal)}}</text></view><button class="btn" :disabled="!selectedCart.length||busy" @tap="checkout">去下单（{{selectedCart.length}}）</button></view>
 </template>
 <template v-else-if="screen==='checkout'">
  <view class="card" @tap="go('address')"><text class="strong">收货信息</text><view class="row mt16"><FIcon name="pin"/><view class="grow"><text class="strong">{{store?.name}} · 后厨收货处</text><text class="small muted block mt8">{{store?.address}}</text><text class="small block mt8">{{store?.contact}}　{{store?.phone}}</text></view><FIcon name="chevron" :size="17"/></view></view><view class="card"><text class="strong">配送时间</text><picker mode="date" :value="deliveryDate" :start="today()" :end="today(30)" @change="deliveryDate=$event.detail.value"><view class="picker-row"><FIcon name="calendar" :size="19"/><text>{{deliveryDate}}</text><FIcon name="chevron" :size="16"/></view></picker><picker :range="slots" :value="slots.indexOf(deliverySlot)" @change="deliverySlot=slots[$event.detail.value]"><view class="picker-row"><FIcon name="clock" :size="19"/><text>{{deliverySlot}}</text><FIcon name="chevron" :size="16"/></view></picker></view><view class="card"><text class="strong">商品清单</text><view v-for="i in checkoutCart" :key="i.id" class="item-row"><FoodPhoto :image="i.image"/><view class="grow"><text>{{i.name}}</text><text class="block small muted mt4">¥{{money(i.price)}} / {{i.unit}}</text></view><text class="small">{{i.quantity}}{{i.unit}}</text><text class="price strong small">¥{{money(lineAmount(i.price,i.quantity))}}</text></view></view><view class="card"><text class="strong">订单备注</text><textarea v-model="remark" placeholder="例如：请在后厨入口交货" maxlength="500" class="note-input" aria-label="订单备注"/></view><view class="card row"><FIcon name="wallet"/><view><text class="strong">结算方式</text><text class="block mt8">线下结算</text><text class="muted small block mt4">由平台与门店统一对账</text></view></view><view class="action-bar"><view class="grow">合计 <text class="price strong">¥{{money(checkoutTotal)}}</text></view><button class="btn" :disabled="busy||!checkoutCart.length" :loading="busy" @tap="submitOrder">提交订单</button></view>
 </template>
 <template v-else-if="screen==='orders'">
  <view class="search"><FIcon name="search" :size="18"/><input v-model="search" placeholder="搜索订单编号、食材" aria-label="搜索订单"/></view><view class="tabs scroll-tabs"><button v-for="t in orderTabs" :key="t.value" :class="{active:status===t.value}" @tap="status=t.value">{{t.label}}</button></view><OrderCard v-for="o in filteredOrders" :key="o.id" :order="o"/><view v-if="!filteredOrders.length" class="empty"><FIcon name="order" :size="40"/><text>暂无相关订单</text><text class="muted small">下单后可在这里跟踪配送进度</text></view>
 </template>
 <template v-else-if="screen==='detail'">
  <template v-if="order"><view class="status-hero row"><FIcon name="truck" :size="42" white/><view><text class="large-title">{{statuses[order.status]}}</text><text class="block small mt8">{{order.delivery_date}} {{order.delivery_slot}} 送达</text></view></view><view class="order-progress"><view v-for="(s,index) in progress" :key="s.value" :class="{done:progressIndex>=index}"><text class="progress-dot">{{progressIndex>=index?'✓':''}}</text><text>{{s.label}}</text></view></view><view v-if="order.status==='issue'" class="notice warning">异常原因：{{order.issue}}</view><view class="card"><text class="strong">供应商信息</text><view class="row mt12"><view class="avatar"><FIcon name="leaf"/></view><view class="grow"><text class="strong">{{order.supplierName}}</text><text class="small muted block mt4">联系电话：{{order.supplierPhone}}</text></view><button class="icon-button" aria-label="联系供应商" @tap="call(order.supplierPhone)"><FIcon name="phone"/></button></view><view class="divider"/><text class="strong">收货信息</text><view class="row mt12"><FIcon name="pin"/><view><text>{{order.storeName}} · 后厨收货处</text><text class="small muted block mt8">{{order.address}}</text><text class="small muted block mt8">{{order.contact}}　{{order.phone}}</text></view></view></view><view class="card"><text class="strong">商品清单</text><view v-for="i in order.items" :key="i.productId" class="item-row"><FoodPhoto :image="i.image"/><view class="grow"><text>{{i.name}}</text><text class="muted small block mt4">¥{{money(i.price)}} / {{i.unit}}</text></view><text class="small">{{i.quantity}}{{i.unit}}</text><text class="price small">¥{{money(i.amount)}}</text></view><view class="row between mt16"><text>合计</text><text class="price strong">¥{{money(order.total)}}</text></view></view><view class="card"><text class="strong">订单信息</text><view class="spec-list mt12"><view><text>订单编号</text><text>{{order.order_no}}</text></view><view><text>下单时间</text><text>{{dateTime(order.created_at)}}</text></view><view><text>结算方式</text><text>线下结算</text></view><view><text>订单备注</text><text>{{order.remark||'无'}}</text></view></view></view><view v-if="order.events.length" class="card"><text class="strong">订单进度</text><view v-for="(e,i) in order.events" :key="i" class="timeline-row"><text class="strong small">{{eventLabels[e.action]||e.action}}</text><text class="muted small">{{dateTime(e.created_at)}}</text></view></view><view v-if="order.status==='issue'&&state.user.role==='admin'" class="card"><text class="strong">异常处理说明</text><textarea v-model="issueNote" placeholder="填写处理结果，将恢复至异常前状态" class="note-input"/><button class="btn full mt12" :disabled="busy" @tap="doAction('resolve')">处理完成并恢复订单</button></view><view v-if="!['completed','cancelled','issue'].includes(order.status)" class="card"><textarea v-model="issueNote" placeholder="缺货、少送或配送异常，请填写具体情况" class="note-input" maxlength="500"/><button class="btn secondary full mt8" :disabled="busy||!issueNote.trim()" @tap="doAction('report')">提交异常反馈</button></view><view class="action-bar"><button class="btn secondary grow" @tap="call(order.supplierPhone)">联系供应商</button><button v-if="order.status==='pending'" class="btn secondary grow" :disabled="busy" @tap="doAction('cancel')">取消订单</button><button v-if="order.status==='delivered'&&state.user.role==='store'" class="btn grow" :disabled="busy" @tap="doAction('receive')">确认收货</button><text v-if="order.status==='completed'" class="badge completed">已完成收货</text></view></template><view v-else class="empty">订单不存在或无权访问</view>
 </template>
 <template v-else-if="screen==='mine'">
  <view class="profile-head row"><view class="profile-avatar"><FIcon name="user" :size="34"/></view><view><text class="large-title">{{state.user.role==='store'?store?.name:state.user.name}}</text><text class="badge completed ml8">{{state.user.role==='store'?'门店采购员':'供应商'}}</text><text class="muted small block mt8">{{store?.contact||supplier?.contact}}　{{store?.phone||supplier?.phone}}</text></view></view>
  <view v-if="state.user.role==='store'" class="money-panel"><text class="small">本月采购（{{monthStart}}—{{today()}}）</text><text class="block huge-number mt8">¥{{money(billTotal)}}</text><view class="two-columns mt16"><view><text class="small">已结算</text><text class="block strong mt8">¥{{money(billPaid)}}</text></view><view><text class="small">待结算</text><text class="block strong warm mt8">¥{{money(billDue)}}</text></view></view></view><view v-else class="money-panel"><text>配送完成</text><text class="huge-number block mt8">{{state.orders.filter(o=>o.status==='completed').length}} <text class="unit">单</text></text><text class="small block mt8">负责门店 {{state.stores.length}}家</text></view>
  <view class="quick-actions card"><button v-for="t in mineStatuses" :key="t.value" @tap="go(state.user.role==='store'?'orders':'supplierOrders',{filter:t.value})"><FIcon :name="t.icon" :size="25"/><text>{{t.label}}</text><text class="mini-count">{{state.orders.filter(o=>o.status===t.value).length}}</text></button></view>
  <view class="card menu-list"><button v-for="m in mineMenus" :key="m.screen" @tap="openMenu(m)"><FIcon :name="m.icon"/><text class="grow">{{m.label}}</text><text v-if="m.screen==='supplierInfo'" class="muted small">{{store?.supplierName}}</text><FIcon name="chevron" :size="16"/></button></view><view class="card menu-list"><button @tap="go('help')"><FIcon name="help"/><text class="grow">帮助与反馈</text><FIcon name="chevron" :size="16"/></button><button @tap="go('settings')"><FIcon name="settings"/><text class="grow">账号设置</text><FIcon name="chevron" :size="16"/></button></view><text class="center muted small block mt24">货款由平台统一线下结算</text>
 </template>
 <template v-else-if="screen==='bill'">
  <view class="row between mb16"><text class="strong">{{store?.name}}</text><picker mode="date" :value="dateFrom" @change="dateFrom=$event.detail.value"><text class="filter-pill">{{dateFrom}} 起</text></picker><picker mode="date" :value="dateTo" @change="dateTo=$event.detail.value"><text class="filter-pill">至 {{dateTo}}</text></picker></view><view class="light-panel"><view class="row between"><text>本期采购</text><text class="small">共{{billOrders.length}}单</text></view><text class="huge-number block mt8">¥{{money(billTotal)}}</text><view class="two-columns mt16"><view><text class="small muted">已结算</text><text class="strong block mt8">¥{{money(billPaid)}}</text></view><view><text class="small muted">待结算（已收货）</text><text class="price strong block mt8">¥{{money(billDue)}}</text></view></view></view><view class="tabs"><button :class="{active:billTab==='orders'}" @tap="billTab='orders'">订单明细</button><button :class="{active:billTab==='settlements'}" @tap="billTab='settlements'">结算记录</button></view><template v-if="billTab==='orders'"><view v-for="o in billOrders" :key="o.id" class="card" @tap="go('detail',{id:o.id})"><view class="row between"><text class="small">{{o.order_no}}</text><text class="badge" :class="Number(o.paid)>=Number(o.total)?'completed':'pending'">{{Number(o.paid)>=Number(o.total)?'已结清':Number(o.paid)>0?'部分结算':'待结算'}}</text></view><view class="row between mt12"><view class="row thumb-strip"><FoodPhoto v-for="i in o.items.slice(0,3)" :key="i.productId" :image="i.image"/></view><view class="align-right"><text class="strong">¥{{money(o.total)}}</text><text class="small muted block mt8">{{String(o.created_at).slice(0,10)}} ›</text></view></view></view></template><template v-else><view v-for="s in billSettlements" :key="s.id" class="card"><view class="row between"><text>{{s.settlement_date}}</text><text class="strong">¥{{money(s.amount)}}</text></view><text class="small muted block mt8">{{s.note}}</text></view></template><view v-if="!(billTab==='orders'?billOrders:billSettlements).length" class="empty">所选日期暂无记录</view><button class="btn secondary full" :disabled="busy" @tap="downloadBill"><FIcon name="download" :size="18"/>导出账单</button><text class="muted small center block mt12">线下对账结算，已收货订单可登记收款</text>
 </template>
 <template v-else-if="screen==='address'">
  <view class="card"><text class="h2">{{store?.name}} · 收货信息</text><label class="field"><text>联系人</text><input v-model="profile.contact" aria-label="联系人"/></label><label class="field"><text>联系电话</text><input v-model="profile.phone" type="number" aria-label="联系电话"/></label><label class="field"><text>详细收货地址</text><textarea v-model="profile.address" maxlength="300" aria-label="收货地址"/></label><text class="small muted block mt12">修改仅用于后续新订单，历史订单保留原收货信息。</text><button class="btn full mt24" :disabled="busy" @tap="saveProfile">保存收货信息</button></view>
 </template>
 <template v-else-if="screen==='settings'">
  <view class="card"><text class="h2">账号信息</text><view class="spec-list mt16"><view><text>用户名</text><text>{{state.user.username}}</text></view><view><text>账号名称</text><text>{{state.user.name}}</text></view><view><text>账号角色</text><text>{{roles[state.user.role]}}</text></view></view></view><view class="card"><text class="h2">修改密码</text><label class="field"><text>原密码</text><input v-model="password.oldPassword" password aria-label="原密码"/></label><label class="field"><text>新密码</text><input v-model="password.newPassword" password placeholder="至少8位" aria-label="新密码"/></label><label class="field"><text>确认新密码</text><input v-model="password.confirm" password aria-label="确认新密码"/></label><button class="btn full" :disabled="busy" @tap="savePassword">保存新密码</button></view><button class="btn secondary full" @tap="signOut">退出登录</button>
 </template>
 <template v-else-if="screen==='help'">
  <view class="card"><text class="h2">使用帮助</text><view class="help-block"><text class="strong">订单如何分配？</text><text>门店提交订单后，系统按照平台配置的配送关系分配给对应供应商。</text></view><view class="help-block"><text class="strong">如何支付货款？</text><text>系统记录订单和账单，货款由平台与门店线下对账结算。</text></view><view class="help-block"><text class="strong">缺货或配送有问题？</text><text>进入订单详情填写异常反馈，平台处理后会同步订单状态。</text></view></view><view class="card"><text class="h2">意见反馈</text><textarea v-model="feedback" class="note-input" placeholder="请描述您遇到的问题，平台管理员可以查看并处理" maxlength="1000"/><button class="btn full mt16" :disabled="busy||!feedback.trim()" @tap="submitFeedback">提交反馈</button></view>
 </template>
</view>
</template>
<script setup>
import {ref,computed,watch,inject} from 'vue';import FIcon from './FIcon.vue';import FoodPhoto from './FoodPhoto.vue';import Stepper from './Stepper.vue';import OrderCard from './OrderCard.vue';import {state,go,back,mutate,confirm,toast,today,key,money,statuses,roles,call,exportFile,logout,request,lineAmount,quantitySummary} from '../lib/food'
const props=defineProps({screen:String,itemId:String,filter:String});const {run,busy}=inject('app');const search=ref(''),category=ref('全部'),categories=['全部','蔬菜','肉禽','粮油'];const store=computed(()=>state.stores.find(s=>s.id===state.user?.storeId)),supplier=computed(()=>state.suppliers.find(s=>s.id===state.user?.supplierId));
const products=computed(()=>state.products.filter(p=>p.active&&(category.value==='全部'||p.category===category.value)&&p.name.includes(search.value)));const product=computed(()=>state.products.find(p=>String(p.id)===props.itemId));const productQuantity=ref(1);watch(()=>product.value?.id,id=>{if(id)productQuantity.value=Number(product.value.minimum)},{immediate:true});
const excluded=ref([]);const cart=computed(()=>state.cart.map(c=>({...state.products.find(p=>p.id===c.productId),id:c.productId,quantity:c.quantity})).map(c=>c.name?c:{...c,name:'商品已下架',price:0,unit:'斤',image:0,minimum:1}));const selectedCart=computed(()=>cart.value.filter(i=>!excluded.value.includes(i.id)));const cartTotal=computed(()=>selectedCart.value.reduce((s,i)=>s+lineAmount(i.price,i.quantity),0));const cartQuantity=computed(()=>quantitySummary(selectedCart.value));
const checkoutIds=uni.getStorageSync('food_checkout_'+state.user?.id)||[];const checkoutCart=computed(()=>cart.value.filter(i=>checkoutIds.includes(i.id)));const checkoutTotal=computed(()=>checkoutCart.value.reduce((s,i)=>s+lineAmount(i.price,i.quantity),0));const deliveryDate=ref(today(1)),slots=['06:00—08:00','08:00—10:00','14:00—16:00'],deliverySlot=ref(slots[0]),remark=ref(''),requestKey=key();
const status=ref(props.filter||''),orderTabs=[{value:'',label:'全部'},{value:'pending',label:'待接单'},{value:'delivering',label:'配送中'},{value:'delivered',label:'待收货'},{value:'completed',label:'已完成'}];const filteredOrders=computed(()=>state.orders.filter(o=>(!status.value||o.status===status.value)&&(!search.value||o.order_no.includes(search.value)||o.items.some(i=>i.name.includes(search.value)))));const order=computed(()=>state.orders.find(o=>String(o.id)===props.itemId));const issueNote=ref('');const progress=[{value:'pending',label:'已下单'},{value:'preparing',label:'已接单'},{value:'delivering',label:'配送中'},{value:'completed',label:'已完成'}];const progressIndex=computed(()=>({pending:0,preparing:1,ready:1,delivering:2,delivered:2,completed:3})[order.value?.status]??0);const eventLabels={submit:'门店已下单',accept:'供应商已接单',packed:'食材已备齐',start:'开始配送',deliver:'供应商已送达',receive:'门店确认收货',cancel:'订单已取消',report:'已提交异常',resolve:'平台已处理异常'};const dateTime=v=>String(v||'').replace('T',' ').slice(0,16);
const monthStart=today().slice(0,8)+'01',dateFrom=ref(monthStart),dateTo=ref(today()),billTab=ref('orders');const inPeriod=v=>String(v).slice(0,10)>=dateFrom.value&&String(v).slice(0,10)<=dateTo.value;const billOrders=computed(()=>state.orders.filter(o=>o.status!=='cancelled'&&inPeriod(o.created_at)));const billSettlements=computed(()=>state.settlements.filter(s=>inPeriod(s.settlement_date)));const billTotal=computed(()=>billOrders.value.reduce((s,o)=>s+Number(o.total),0)),billPaid=computed(()=>billOrders.value.reduce((s,o)=>s+Number(o.paid),0)),billDue=computed(()=>billOrders.value.filter(o=>o.status==='completed').reduce((s,o)=>s+Number(o.total)-Number(o.paid),0));
const mineStatuses=[{value:'pending',label:'待接单',icon:'order'},{value:'ready',label:'待配送',icon:'truck'},{value:'delivered',label:'待收货',icon:'box'},{value:'completed',label:'已完成',icon:'check'}];const mineMenus=computed(()=>state.user.role==='store'?[{screen:'bill',label:'我的账单',icon:'wallet'},{screen:'address',label:'收货地址',icon:'pin'},{screen:'address',label:'联系人信息',icon:'phone'},{screen:'supplierInfo',label:'配送供应商',icon:'truck'}]:[{screen:'history',label:'历史订单与汇总',icon:'chart'},{screen:'delivery',label:'配送任务',icon:'truck'}]);
const profile=ref({contact:store.value?.contact||'',phone:store.value?.phone||'',address:store.value?.address||''});watch(store,s=>{if(s&&!profile.value.contact)profile.value={contact:s.contact,phone:s.phone,address:s.address}});const password=ref({oldPassword:'',newPassword:'',confirm:''}),feedback=ref('');
function setCart(id,quantity){run(()=>mutate('/cart',{productId:id,quantity},''))}function toggleItem(id){excluded.value=excluded.value.includes(id)?excluded.value.filter(i=>i!==id):[...excluded.value,id]}
function add(p){run(()=>mutate('/cart',{productId:p.id,quantity:Number(state.cart.find(c=>c.productId===p.id)?.quantity||0)+Number(p.minimum)},'已加入购物车'))}function addProduct(){run(()=>mutate('/cart',{productId:product.value.id,quantity:productQuantity.value},'已加入购物车'))}
function checkout(){if(selectedCart.value.some(i=>!i.active))return toast('请移除已下架的食材');uni.setStorageSync('food_checkout_'+state.user.id,selectedCart.value.map(i=>i.id));go('checkout')}
function submitOrder(){run(async()=>{const o=await mutate('/orders',{requestKey,items:checkoutCart.value.map(i=>({productId:i.id,quantity:i.quantity})),deliveryDate:deliveryDate.value,deliverySlot:deliverySlot.value,remark:remark.value},'下单成功，已分配供应商');uni.removeStorageSync('food_checkout_'+state.user.id);go('detail',{id:o.id},true)})}
function doAction(action){run(async()=>{if(await confirm(({cancel:'确认取消订单？',receive:'确认食材已收到？',report:'提交异常反馈？',resolve:'确认异常已解决？'})[action]))await mutate('/orders/'+order.value.id+'/action',{action,note:issueNote.value},'订单已更新')})}
function openMenu(m){if(m.screen==='supplierInfo'){if(store.value?.supplierPhone)call(store.value.supplierPhone);else toast('门店尚未绑定供应商')}else go(m.screen)}
function downloadBill(){run(()=>exportFile(billTab.value==='orders'?'orders':'settlements',{from:dateFrom.value,to:dateTo.value,excludeCancelled:billTab.value==='orders'?'true':''}))}
function saveProfile(){run(async()=>{await mutate('/profile',profile.value);back()})}
function savePassword(){run(async()=>{if(password.value.newPassword!==password.value.confirm)throw new Error('两次输入的新密码不一致');const role=state.user.role;await request('/profile',password.value);await logout(role);toast('密码已更新，请重新登录')})}
function signOut(){run(async()=>{if(await confirm('退出当前账号？'))await logout()})}
function submitFeedback(){run(async()=>{await mutate('/feedback',{content:feedback.value},'反馈已提交，平台可查看');feedback.value=''})}
</script>
